// Stage 2 normalization with audit (Item 3 of pipeline hardening plan).
// Inlined from normalizationAuditor.js.

const LOW_CONFIDENCE_THRESHOLD = 0.7;

function slugify(text) {
  return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}
function normalizeText(text) { return String(text || '').replace(/\s+/g, ' ').trim(); }
function titleCase(text) {
  return normalizeText(text).split(/\s+/).filter(Boolean).map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join(' ');
}
function parseDate(v) { const ts = Date.parse(v); return Number.isFinite(ts) ? ts : Date.now(); }
function isoDate(ts) { return new Date(ts).toISOString().slice(0, 10); }
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }
function round2(v) { return Math.round(v * 100) / 100; }
function hash(s) { let h = 0; const x = String(s || ''); for (let i = 0; i < x.length; i++) { h = (h << 5) - h + x.charCodeAt(i); h |= 0; } return Math.abs(h).toString(36); }
function looksLikeJunk(term) {
  const t = String(term || '').trim();
  if (!t || t.length < 3 || t.length > 60) return true;
  if (/[A-Z]/.test(t) && !/\s/.test(t)) return true;
  if (/[:{}<>]/.test(t)) return true;
  if (/\b(middleware|responder|resource|provider|wrapper|request|parser|loader|cookieparser|sessionparser|csrfrequest)\b/i.test(t)) return true;
  return false;
}

function confidenceFor(group, candidate) {
  const a = String(candidate || '').toLowerCase();
  const b = String(group.term || '').toLowerCase();
  if (!a || !b) return 0;
  if (a === b) return 1;
  const ta = new Set(a.split(/\s+/).filter(Boolean));
  const tb = new Set(b.split(/\s+/).filter(Boolean));
  const inter = [...ta].filter((t) => tb.has(t)).length;
  const union = new Set([...ta, ...tb]).size || 1;
  const j = inter / union;
  const lp = a.length < 4 ? 0.5 : 1;
  return Math.min(1, j * lp + (j >= 0.5 ? 0.1 : 0));
}

function logRow(input) {
  const i = input || {};
  return {
    log_id: 'norm_' + (i.canonical_id || 'noid') + '_' + hash(i.input_term || '') + '_' + Date.now() + '_' + Math.floor(Math.random() * 1e6),
    run_id: i.run_id || '',
    run_date: i.run_date || '',
    canonical_id: i.canonical_id || '',
    input_term: i.input_term || '',
    decision_type: i.decision_type || '',
    confidence: round2(num(i.confidence)),
    merged_into: i.merged_into || '',
    reason: i.reason || '',
    created_at: new Date().toISOString(),
  };
}

const rawSignals = $('Read raw_signals').all().map((it) => it.json || {});
const existingRows = $('Read normalized_terms').all().map((it) => it.json || {});
const existing = new Set(existingRows.map((r) => String(r.canonical_id || '').trim()).filter(Boolean));

const runId = 'run_wf_normalize_terms_' + Date.now();
const runDate = new Date().toISOString().slice(0, 10);
const runStarted = new Date().toISOString();

const groups = new Map();
const logRows = [];
const watchRows = [];
const stats = { created: 0, merged: 0, skipped: 0, low_confidence: 0, duplicates: 0 };
const signalLinks = [];

for (const raw of rawSignals) {
  const signalId = String(raw.signal_id || '').trim();
  const term = normalizeText(raw.term);
  if (looksLikeJunk(term)) {
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: '', input_term: term || raw.term, decision_type: 'skipped', confidence: 0, reason: 'low_quality_term' }));
    stats.skipped += 1;
    continue;
  }
  if (!term || signalId === 'ERROR' || term.toLowerCase() === 'fetch_failed') {
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: '', input_term: term || raw.term, decision_type: 'skipped', confidence: 0, reason: 'invalid_or_sentinel' }));
    stats.skipped += 1;
    continue;
  }
  const canonicalId = 'norm_' + slugify(term);
  if (existing.has(canonicalId)) {
    stats.duplicates += 1;
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: canonicalId, input_term: term, decision_type: 'skipped', confidence: 1, merged_into: canonicalId, reason: 'already_canonical' }));
    signalLinks.push({ signal_id: signalId, canonical_id: canonicalId });
    continue;
  }
  const collectedAt = normalizeText(raw.date_collected) || new Date().toISOString();
  const collectedTs = parseDate(collectedAt);
  const market = normalizeText(raw.market) || 'UK';
  const category = normalizeText(raw.category || raw.source || 'general') || 'general';

  let group = groups.get(canonicalId);
  const isNew = !group;
  if (isNew) {
    group = { canonicalId, term, firstTs: collectedTs, lastTs: collectedTs, aliases: new Set([term]), markets: new Set(), categoryCounts: new Map() };
    groups.set(canonicalId, group);
  }
  group.firstTs = Math.min(group.firstTs, collectedTs);
  group.lastTs = Math.max(group.lastTs, collectedTs);
  group.aliases.add(term);
  const related = normalizeText(raw.related_term);
  if (related) {
    for (const part of related.split('|')) {
      const alias = normalizeText(part);
      if (alias) group.aliases.add(alias);
    }
  }
  group.markets.add(market);
  group.categoryCounts.set(category, (group.categoryCounts.get(category) || 0) + 1);

  const conf = confidenceFor(group, term);
  const decisionType = isNew ? 'created' : 'merged';
  logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: canonicalId, input_term: term, decision_type: decisionType, confidence: conf, merged_into: isNew ? '' : canonicalId, reason: isNew ? 'new_canonical_term' : 'alias_into_existing_group' }));
  if (isNew) stats.created += 1; else stats.merged += 1;

  if (decisionType === 'merged' && conf < LOW_CONFIDENCE_THRESHOLD) {
    stats.low_confidence += 1;
    logRows.push(logRow({ run_id: runId, run_date: runDate, canonical_id: canonicalId, input_term: term, decision_type: 'low_confidence', confidence: conf, merged_into: canonicalId, reason: 'merge_below_threshold' }));
    watchRows.push({
      watch_id: 'watch_norm_' + canonicalId + '_' + Date.now() + '_' + Math.floor(Math.random() * 1e6),
      canonical_id: canonicalId,
      reason: 'normalization_low_confidence',
      review_after: runDate,
      notes: 'Auto-flagged: alias \'' + term + '\' merged at confidence ' + conf.toFixed(2),
    });
  }
  signalLinks.push({ signal_id: signalId, canonical_id: canonicalId });
}

const normalizedRows = Array.from(groups.values()).map((g) => {
  let primaryCategory = 'general';
  let max = 0;
  for (const [c, k] of g.categoryCounts.entries()) { if (k > max) { max = k; primaryCategory = c; } }
  return {
    json: {
      canonical_id: g.canonicalId,
      date_first_seen: isoDate(g.firstTs),
      date_last_seen: isoDate(g.lastTs),
      canonical_term: titleCase(g.term),
      aliases: Array.from(g.aliases).join('|'),
      language: 'en',
      market: Array.from(g.markets).join('|'),
      primary_category: primaryCategory,
      status: 'active',
    },
  };
});

if (!normalizedRows.length) {
  const now = new Date().toISOString();
  return [
    { json: { __noRows: true, __runMeta: { run_id: runId, run_started: runStarted }, __logRows: logRows, __watchRows: watchRows, __stats: stats, __signal_links: signalLinks, run_id: runId, run_started: runStarted, run_finished: now, job_name: 'wf_normalize_terms', rows_added: 0, rows_updated: 0, status: 'no_rows', error_log: '' } },
  ];
}

return normalizedRows.concat([
  { json: { __sidecar: true, __runMeta: { run_id: runId, run_started: runStarted }, __logRows: logRows, __watchRows: watchRows, __stats: stats, __signal_links: signalLinks } },
]);

// Filter the sidecar/no-rows item out so the Sheets append only sees real rows.
const rows = $input.all().filter((it) => it.json && !it.json.__sidecar && !it.json.__noRows);
return rows;

const sidecars = $('Build normalized terms').all().map((it) => it.json || {}).filter((j) => j.__sidecar || j.__noRows);
const sidecar = sidecars[sidecars.length - 1] || {};
const meta = sidecar.__runMeta || { run_id: 'run_wf_normalize_terms_' + Date.now(), run_started: new Date().toISOString() };
const now = new Date().toISOString();
return [
  {
    json: {
      run_id: meta.run_id,
      run_started: meta.run_started,
      run_finished: now,
      job_name: 'wf_normalize_terms',
      rows_added: 0,
      rows_updated: 0,
      status: 'success',
      error_log: '',
    },
  },
];

// Pull sidecar from Build normalized terms and emit normalization_log rows.
const sidecars = $('Build normalized terms').all().map((it) => it.json || {}).filter((j) => j.__sidecar || j.__noRows);
const sidecar = sidecars[sidecars.length - 1] || {};
const rows = (sidecar.__logRows || []).map((r) => ({ json: r }));
return rows.length ? rows : [{ json: { __empty: true } }];

const sidecars = $('Build normalized terms').all().map((it) => it.json || {}).filter((j) => j.__sidecar || j.__noRows);
const sidecar = sidecars[sidecars.length - 1] || {};
const rows = (sidecar.__watchRows || []).map((r) => ({ json: r }));
return rows.length ? rows : [{ json: { __empty: true } }];

const sidecars = $('Build normalized terms').all().map((it) => it.json || {}).filter((j) => j.__sidecar || j.__noRows);
const sidecar = sidecars[sidecars.length - 1] || {};
const meta = sidecar.__runMeta || { run_id: 'run_wf_normalize_terms_' + Date.now(), run_started: new Date().toISOString() };
const stats = sidecar.__stats || { created: 0, merged: 0, skipped: 0, low_confidence: 0, duplicates: 0 };
const rowsIn = $('Read raw_signals').all().length;
const rowsOut = $('Build normalized terms').all().filter((it) => !(it.json && (it.json.__sidecar || it.json.__noRows))).length;
const startedAt = meta.run_started || new Date().toISOString();
const endedAt = new Date().toISOString();
const durationMs = Math.max(0, Date.parse(endedAt) - Date.parse(startedAt));
const status = stats.low_confidence > 0 ? 'warn' : (rowsOut === 0 ? 'success' : 'success');
return [
  { json: { log_id: 'slog_wf_normalize_terms_normalize_' + Date.now() + '_start', run_id: meta.run_id, workflow_name: 'wf_normalize_terms', stage_name: 'normalize', event_type: 'start', started_at: startedAt, ended_at: null, duration_ms: 0, rows_in: rowsIn, rows_out: 0, error_count: 0, status: 'running', error_summary: '', attempt_number: 1, parent_log_id: '', metadata_json: '{}' } },
  { json: { log_id: 'slog_wf_normalize_terms_normalize_' + Date.now() + '_end', run_id: meta.run_id, workflow_name: 'wf_normalize_terms', stage_name: 'normalize', event_type: 'end', started_at: startedAt, ended_at: endedAt, duration_ms: durationMs, rows_in: rowsIn, rows_out: rowsOut, error_count: 0, status, error_summary: '', attempt_number: 1, parent_log_id: '', metadata_json: JSON.stringify(stats) } },
];

const sidecars = $('Build normalized terms').all().map((it) => it.json || {}).filter((j) => j.__sidecar || j.__noRows);
const sidecar = sidecars[sidecars.length - 1] || {};
const meta = sidecar.__runMeta || { run_id: 'run_wf_normalize_terms_' + Date.now(), run_started: new Date().toISOString() };
const stats = sidecar.__stats || { created: 0, merged: 0, skipped: 0, low_confidence: 0, duplicates: 0 };
const rowsAdded = $('Build normalized terms').all().filter((it) => !(it.json && (it.json.__sidecar || it.json.__noRows))).length;
const now = new Date().toISOString();
return [
  {
    json: {
      run_id: meta.run_id,
      run_started: meta.run_started,
      run_finished: now,
      job_name: 'wf_normalize_terms',
      rows_added: rowsAdded,
      rows_updated: 0,
      status: stats.low_confidence > 0 ? 'success_with_rejects' : 'success',
      error_log: stats.low_confidence > 0 ? ('low_confidence=' + stats.low_confidence) : '',
      sources_summary_json: (stats),
      stage_log_root_id: null,
    },
  },
];

const items = $('Build normalized terms').all();
let links = [];
for (const it of items) {
  const j = it.json || {};
  if (j.__sidecar && Array.isArray(j.__signal_links)) links = j.__signal_links;
  if (j.__noRows && Array.isArray(j.__signal_links)) links = j.__signal_links;
}
return [{ json: { signal_links_json: JSON.stringify(links) } }];

const CONTRACT_VERSION = "2026-05-01";
function slugify(text) {
  return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}
function normalizeText(text) { return String(text || '').replace(/\\s+/g, ' ').trim(); }
function looksLikeJunk(term) {
  const t = String(term || '').trim();
  if (!t || t.length < 3 || t.length > 60) return true;
  if (/[A-Z]/.test(t) && !/\\s/.test(t)) return true;
  if (/[:{}<>]/.test(t)) return true;
  return false;
}
function hashDedupe(s) {
  let h = 0;
  const x = String(s || '');
  for (let i = 0; i < x.length; i++) { h = (h << 5) - h + x.charCodeAt(i); h |= 0; }
  return Math.abs(h).toString(36);
}
function tokenize(h) {
  return String(h || '').toLowerCase().replace(/[^a-z0-9\\s]+/g, ' ').split(/\\s+/).filter(Boolean);
}
function deriveAudience(termLower) {
  const IDENTITY_WORDS = ["mom","dad","teacher","nurse","dog","cat","wife","husband","grandma","grandpa","auntie","uncle","sister","brother","friend","girl","guy","queen","king","boss","lover","fan","nerd","geek","pro","hero","rebel","doctor","lawyer","chef","baker","runner","hiker","gamer","reader","gardener","crafter"];
  const tk = new Set(tokenize(termLower));
  for (const t of IDENTITY_WORDS) { if (tk.has(t)) return { audience_tags: [t], primary_audience: t }; }
  return { audience_tags: [] };
}
function deriveSeasonality(termLower) {
  const OCCASION_WORDS = ["birthday","christmas","halloween","valentine","mother","father","wedding","anniversary","graduation","baby","shower","new year","easter","thanksgiving","holiday","party"];
  const tk = new Set(tokenize(termLower));
  for (const t of OCCASION_WORDS) { if (tk.has(t)) return { flags: [t], has_occasion: true }; }
  return { flags: [], has_occasion: false };
}
function deriveRisk(termLower) {
  const BRAND = ["disney","marvel","nfl","nba","mlb","nhl","taylor","swift","beyonce","kardashian","trump","biden","harry","styles","billie","eilish","pokemon","minecraft","roblox","fortnite","barbie","nike","adidas","supreme","gucci","nasa","ncaa"];
  const NEWS = ["election","war","shooting","flood","earthquake","covid","pandemic","terrorist","riot","protest","hostage"];
  const tk = new Set(tokenize(termLower));
  const hit = [];
  for (const t of BRAND) if (tk.has(t)) hit.push(t);
  if (hit.length) return { level: 'high', matched_terms: hit, has_high_risk: true };
  const n = [];
  for (const t of NEWS) if (tk.has(t)) n.push(t);
  if (n.length) return { level: 'moderate', matched_terms: n, has_high_risk: false };
  return { level: 'low', matched_terms: [], has_high_risk: false };
}

const rawSignals = $('Read raw_signals').all().map((it) => it.json || {}).filter((r) => String(r.signal_id || '').trim() && String(r.signal_id).trim() !== '__empty__');
const cfgRows = $('Read sources_config').all().map((it) => it.json || {});
const typeBySource = {};
for (const c of cfgRows) {
  const sn = String(c.source_name || '').trim();
  if (sn) typeBySource[sn] = String(c.source_type || 'unknown');
}
const sidecars = $('Build normalized terms').all().map((it) => it.json || {}).filter((j) => j.__sidecar || j.__noRows);
const sidecar = sidecars[sidecars.length - 1] || {};
const runMeta = sidecar.__runMeta || {};
const intakeRunId = runMeta.run_id || '';

const byCanon = new Map();
for (const raw of rawSignals) {
  const term = normalizeText(raw.term);
  if (looksLikeJunk(term)) continue;
  const sid = String(raw.signal_id || '').trim();
  if (!sid || sid === '__empty__') continue;
  const canonicalId = 'norm_' + slugify(term);
  if (!byCanon.has(canonicalId)) byCanon.set(canonicalId, { signal_ids: [], sources: [], observed: [] });
  const b = byCanon.get(canonicalId);
  b.signal_ids.push(sid);
  b.sources.push(String(raw.source || '').trim());
  b.observed.push(raw.date_collected);
}

const normRows = $('Filter normalized rows').all().map((it) => it.json || {}).filter((j) => j.canonical_id);
const out = [];
for (const row of normRows) {
  const canonicalId = String(row.canonical_id || '').trim();
  if (!canonicalId) continue;
  const dedupeKey = canonicalId.startsWith('norm_') ? canonicalId.slice(5) : canonicalId;
  const agg = byCanon.get(canonicalId) || { signal_ids: [], sources: [], observed: [] };
  const sources = agg.sources.filter(Boolean);
  const primarySource = sources[0] || 'google_trends';
  const sourceType = typeBySource[primarySource] || 'unknown';
  const termLower = String(row.canonical_term || dedupeKey || '').toLowerCase();
  const audience = deriveAudience(termLower);
  const season = deriveSeasonality(termLower);
  const risk = deriveRisk(termLower);
  const lineage = {
    raw_signal_ids: [...new Set(agg.signal_ids)],
    normalized_term_id: canonicalId,
    intake_run_id: intakeRunId,
  };
  const signalId = 'cs_' + hashDedupe(dedupeKey + '|' + CONTRACT_VERSION) + '_' + CONTRACT_VERSION;
  let observedAt = null;
  for (const o of agg.observed) {
    const d = new Date(o);
    if (Number.isFinite(d.getTime())) {
      if (!observedAt || d < observedAt) observedAt = d;
    }
  }
  out.push({
    signal_id: signalId,
    contract_version: CONTRACT_VERSION,
    source_type: sourceType,
    source_name: primarySource,
    source_record_id: null,
    intake_run_id: intakeRunId,
    observed_at: observedAt ? observedAt.toISOString() : null,
    ingested_at: new Date().toISOString(),
    normalized_topic: String(row.canonical_term || ''),
    normalized_niche: String(row.primary_category || ''),
    normalized_sub_niche: null,
    audience_hint: JSON.stringify(audience),
    product_type_hints: JSON.stringify([]),
    trend_metrics: JSON.stringify({ source_family_counts: {} }),
    sentiment_metrics: JSON.stringify(null),
    competition_metrics: JSON.stringify(null),
    seasonality_hint: JSON.stringify(season),
    enrichment: JSON.stringify(null),
    risk_flags: JSON.stringify(risk),
    quality_score: null,
    lineage: JSON.stringify(lineage),
    dedupe_key: dedupeKey,
    status: risk.has_high_risk ? 'quarantined' : 'ready',
  });
}
return [{ json: { canonical_signals_rows: out } }];
